package ai.neu205.one;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;
/** Phone-speaker first, one session control; setup and metadata stay tucked away. */
public final class MainActivity extends Activity {
 private final Handler handler=new Handler(Looper.getMainLooper());private TextView status,question,answer,sources;private Button orb;private LinearLayout setup;private boolean pendingStart;private ImportController imports;
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView label(String value,int size,int color){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(8),0,dp(8));return v;}
 private final Runnable refresh=new Runnable(){public void run(){status.setText(ConversationService.detail);question.setText(ConversationService.question.isEmpty()?"What would you like to understand?":ConversationService.question);answer.setText(ConversationService.answer);sources.setText(ConversationService.pages.isEmpty()?"": "Textbook · digital PDF pages "+ConversationService.pages);orb.setText(ConversationService.active()?"Stop":"Start");handler.postDelayed(this,200);}};
 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(Color.rgb(13,20,28));getWindow().setNavigationBarColor(Color.rgb(13,20,28));
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Color.rgb(13,20,28));LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setGravity(Gravity.CENTER_HORIZONTAL);root.setPadding(dp(26),dp(36),dp(26),dp(28));scroll.addView(root);
  TextView title=label("NEU205  ONE",17,0xffa4d7cd);title.setLetterSpacing(.2f);root.addView(title);root.addView(label("Space to understand.",30,0xffedf4f2));root.addView(label("Private neuroscience conversation · phone speaker",13,0xff9aa9ad));
  status=label("Ready",21,0xffa4d7cd);root.addView(status);root.addView(label("Hold the orb to interrupt and ask again.",12,0xff9aa9ad));
  orb=new Button(this);orb.setText(R.string.start);orb.setAllCaps(false);orb.setTextSize(25);orb.setTextColor(0xff122724);GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xffbcebd8,0xff72bfb5});bg.setShape(GradientDrawable.OVAL);orb.setBackground(bg);LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(dp(154),dp(154));op.topMargin=dp(22);op.bottomMargin=dp(28);root.addView(orb,op);orb.setContentDescription("Start or stop private spoken conversation. Long press while thinking or speaking to interrupt and ask again.");orb.setOnLongClickListener(v->{if(ConversationService.active())startService(new Intent(this,ConversationService.class).setAction("INTERRUPT"));return true;});orb.setOnClickListener(v->{if(ConversationService.active()){pendingStart=false;startService(new Intent(this,ConversationService.class).setAction("STOP"));}else begin();});
  question=label("What would you like to understand?",19,0xffd3e5df);root.addView(question,new LinearLayout.LayoutParams(-1,-2));answer=label("Tap Start once. Ask, listen, and follow up naturally. Stop ends the microphone, model request and speech.",18,0xfff1f3f1);answer.setTextIsSelectable(true);root.addView(answer,new LinearLayout.LayoutParams(-1,-2));sources=label("",12,0xffa4b6b2);root.addView(sources,new LinearLayout.LayoutParams(-1,-2));
  Button settings=new Button(this);settings.setText(R.string.settings);settings.setAllCaps(false);root.addView(settings);setup=new LinearLayout(this);setup.setOrientation(LinearLayout.VERTICAL);setup.setVisibility(View.GONE);root.addView(setup,new LinearLayout.LayoutParams(-1,-2));settings.setOnClickListener(v->setup.setVisibility(setup.getVisibility()==View.GONE?View.VISIBLE:View.GONE));
  setup.addView(label("One-time setup: pair the offline companion on this phone. It must already have the verified full book, Whisper assets and your Qwen model. No model download or Termux modification occurs in this app.",14,0xffc3d0cc));EditText key=new EditText(this);key.setTextColor(Color.WHITE);key.setHintTextColor(0xffaabbb5);key.setHint("Private pairing key");key.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);key.setSingleLine();key.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);setup.addView(key);Button save=new Button(this);save.setText(R.string.save_pairing);setup.addView(save);save.setOnClickListener(v->{if(ConversationService.active()){show("Stop before changing pairing.");return;}String k=key.getText().toString().trim();if(k.length()<32){show("Pairing requires at least 32 characters.");return;}getSharedPreferences("setup",MODE_PRIVATE).edit().putString("key",k).apply();key.setText("");setup.setVisibility(View.GONE);show("Paired · tap Start");});
  CheckBox companion=new CheckBox(this);companion.setText(R.string.start_companion);companion.setTextColor(0xffc3d0cc);companion.setChecked(getSharedPreferences("setup",MODE_PRIVATE).getBoolean("termux_launch",false));setup.addView(companion);
  companion.setOnCheckedChangeListener((button,on)->{if(ConversationService.active()){companion.setChecked(false);show("Stop before changing companion setup.");return;}getSharedPreferences("setup",MODE_PRIVATE).edit().putBoolean("termux_launch",on).apply();if(on && checkSelfPermission("com.termux.permission.RUN_COMMAND")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"com.termux.permission.RUN_COMMAND"},207);});
  setup.addView(label("Optional: first install the supplied isolated companion and explicitly enable Termux external-app commands. Start then launches only its fixed script; no key or arbitrary shell command is sent. This app never changes Termux settings itself.",12,0xffaabbb5));
  Button voice=new Button(this);voice.setText(R.string.voice_settings);setup.addView(voice);voice.setOnClickListener(v->{try{startActivity(new Intent("com.android.settings.TTS_SETTINGS"));}catch(ActivityNotFoundException e){show("Open Android Settings → Text-to-speech.");}});
  setup.addView(label("INTERNET permission is used only for fixed 127.0.0.1:8768. Redirects and remote destinations are rejected. No cloud inference. Microphone starts only after local readiness and installed offline voice checks.",12,0xffaabbb5));
  Button receipt=new Button(this);receipt.setText(R.string.share_metadata);setup.addView(receipt);receipt.setOnClickListener(v->startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,ConversationService.metadata()),"Metadata receipt")));
  CheckBox memory=new CheckBox(this);memory.setText(R.string.v11_memory);memory.setTextColor(0xffc3d0cc);memory.setChecked(getSharedPreferences("setup",MODE_PRIVATE).getBoolean("v11_memory",false));setup.addView(memory);
  memory.setOnCheckedChangeListener((button,on)->{if(ConversationService.active()){memory.setChecked(getSharedPreferences("setup",MODE_PRIVATE).getBoolean("v11_memory",false));show("Stop before changing memory mode.");return;}getSharedPreferences("setup",MODE_PRIVATE).edit().putBoolean("v11_memory",on).apply();});
  CheckBox exam=new CheckBox(this);exam.setText(R.string.v11_exam);exam.setTextColor(0xffc3d0cc);exam.setChecked(getSharedPreferences("setup",MODE_PRIVATE).getBoolean("v11_exam",false));setup.addView(exam);
  exam.setOnCheckedChangeListener((button,on)->{if(ConversationService.active()){exam.setChecked(getSharedPreferences("setup",MODE_PRIVATE).getBoolean("v11_exam",false));show("Stop before changing study mode.");return;}getSharedPreferences("setup",MODE_PRIVATE).edit().putBoolean("v11_exam",on).apply();});
  imports=new ImportController(this,setup);
  setContentView(scroll);
 }
 private void show(String text){ConversationService.detail=text;status.setText(text);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(imports!=null)imports.result(request,result,data);}
 @Override protected void onDestroy(){if(imports!=null)imports.destroy();super.onDestroy();}
 private void begin(){
  if(AssetRepository.importing()){show("Wait for private import verification to finish.");return;}
  if(getSharedPreferences("setup",MODE_PRIVATE).getString("key","").length()<32){setup.setVisibility(View.VISIBLE);show("Pair the offline companion first.");return;}
  pendingStart=true;
  if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},205);return;}
  if(Build.VERSION.SDK_INT>=33 && checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},206);return;}
  pendingStart=false;startForegroundService(new Intent(this,ConversationService.class).setAction("START"));
 }
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(results.length==0 || results[0]!=PackageManager.PERMISSION_GRANTED){pendingStart=false;show("Permission denied. Microphone remains stopped.");return;}if(pendingStart)begin();}
 @Override protected void onResume(){super.onResume();handler.post(refresh);}
 @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
}
